const $=id=>document.getElementById(id);
const completed=new Set();
function feedback(id,errors,success){const box=$('feedback-'+id);box.replaceChildren();box.className='feedback '+(errors.length?'bad':'good');if(errors.length){const title=document.createElement('strong');title.textContent='再检查一下，已经很接近了：';box.append(title);const list=document.createElement('ul');errors.forEach(e=>{const li=document.createElement('li');li.textContent=e;list.append(li);});box.append(list);}else{box.textContent=success;completed.add(id);updateProgress();}}
function updateProgress(){['ui','drag','write'].forEach(id=>{$('done-'+id).textContent=completed.has(id)?'✓':'';});$('progressText').textContent=completed.size+' / 3';$('progressBar').style.width=completed.size/3*100+'%';$('completion').hidden=completed.size!==3;}
function setTab(id,focus=false){document.querySelectorAll('[data-tab]').forEach(b=>{const active=b.dataset.tab===id;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;if(active&&focus)b.focus();$('panel-'+b.dataset.tab).hidden=!active;});}
document.querySelectorAll('[data-tab]').forEach(b=>{b.addEventListener('click',()=>setTab(b.dataset.tab));b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const ids=['ui','drag','write'];let i=ids.indexOf(b.dataset.tab);i=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;setTab(ids[i],true);}});});setTab('ui');
const explanations={method:'POST 表示向服务提交内容，让它处理任务。这里是提交消息并生成回答。GET 则常用于读取已有资源。',url:'Endpoint 是提供服务的具体地址，包括域名和路径。这里的 example.com 只是教学地址；真实调用时，要照着服务商文档填写。',headers:'Authorization 携带用于身份验证的密钥；Bearer 是本例的认证方式。Content-Type: application/json 告诉服务：正文采用 JSON 格式。这里使用 DEMO_KEY，不要输入真实密钥。',body:'JSON 是一种文本数据格式。这里用 model 选择模型，messages 存放消息列表，每条消息都有 role（谁说的）和 content（说什么）。'};
document.querySelectorAll('[data-part]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-part]').forEach(p=>p.classList.toggle('selected',p===b));document.querySelectorAll('.code-highlight').forEach(p=>p.classList.remove('code-highlight'));$('line-'+b.dataset.part).classList.add('code-highlight');$('partExplain').textContent=explanations[b.dataset.part];}));
document.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>{$('quizFeedback').textContent=b.dataset.answer==='right'?'答对了。客户端或它的后端会把消息包装成请求，再发送给模型服务。':'再想想：你输入的是文字，负责把文字包装成网络请求的是应用客户端或它的后端。';document.querySelectorAll('[data-answer]').forEach(x=>x.classList.toggle('correct',x===b&&b.dataset.answer==='right'));}));
function uiBody(){return {model:'demo-small',messages:[{role:'system',content:'你是一位耐心的老师。'},{role:$('role').value||'__选择角色__',content:$('prompt').value||'__填写提问__'}]};}
function updatePreview(){const method=$('method').value||'__选择方法__';$('livePreview').textContent=method+' /v1/chat/completions\n\n'+JSON.stringify(uiBody(),null,2);$('uiResponse').textContent='↙ 检查后，这里会显示模拟响应。';}
['method','role','prompt'].forEach(id=>$(id).addEventListener('input',updatePreview));updatePreview();
const answers={rainbow:'彩虹是阳光进入水滴后发生折射、反射和色散，分出不同颜色而形成的。',eclipse:'月食是地球运行到太阳与月球之间，使月球进入地球影子而变暗的现象。'};
function showResponse(id,answer){const el=$(id);el.hidden=false;el.replaceChildren();const title=document.createElement('strong');title.textContent='200 OK · 模拟响应（预设示例，并未调用模型）';const pre=document.createElement('pre');pre.textContent=JSON.stringify({choices:[{message:{role:'assistant',content:answer}}]},null,2);const note=document.createElement('span');note.textContent='回答在 choices[0].message.content 中。';el.append(title,pre,note);}
$('requestForm').addEventListener('submit',e=>{e.preventDefault();const errors=Lesson.validateUI({method:$('method').value,role:$('role').value,prompt:$('prompt').value});feedback('ui',errors,'填写正确！POST 提交消息，user 表示用户提问，content 存放提问内容。你已完成第一关，可以切换到“拖拽 JSON”。');if(!errors.length)showResponse('uiResponse',answers.rainbow);else $('uiResponse').textContent='先按提示调整，再试一次。';});
const cards=[{id:'assistant',text:'"assistant"'},{id:'content',text:'"用一句话解释彩虹。"'},{id:'messages',text:'"messages"'},{id:'user',text:'"user"'},{id:'model',text:'"model"'}];
let slots={key:null,role:null,content:null},selected=null;
const slotNames={key:'① 字段名',role:'② 角色',content:'③ 提问内容'};
const dragAnnouncement=document.createElement('p');dragAnnouncement.className='drag-help';dragAnnouncement.setAttribute('role','status');$('cardBank').after(dragAnnouncement);
function renderCards(){const bank=$('cardBank');bank.replaceChildren();cards.filter(c=>!Object.values(slots).includes(c.id)).forEach(c=>{const b=document.createElement('button');b.className='card'+(selected===c.id?' selected':'');b.textContent=c.text;b.draggable=true;b.dataset.card=c.id;b.setAttribute('aria-pressed',String(selected===c.id));b.addEventListener('click',()=>{selected=selected===c.id?null:c.id;dragAnnouncement.textContent=selected?'已选中 '+c.text+'，请点击要放入的空位。':'已取消选择。';renderCards();if(selected)document.querySelector('[data-card="'+selected+'"]').focus();});b.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/plain',c.id);e.dataTransfer.effectAllowed='move';});bank.append(b);});document.querySelectorAll('[data-slot]').forEach(b=>{const c=cards.find(x=>x.id===slots[b.dataset.slot]);b.textContent=c?c.text:slotNames[b.dataset.slot];b.classList.toggle('filled',!!c);b.setAttribute('aria-label',slotNames[b.dataset.slot]+(c?'，已放入 '+c.text+'，点击可取回':'，点击放入已选卡片'));});$('dragResponse').hidden=true;}
function place(slot,card){if(!cards.some(c=>c.id===card))return;Object.keys(slots).forEach(k=>{if(slots[k]===card)slots[k]=null;});slots[slot]=card;selected=null;dragAnnouncement.textContent='已放入 '+slotNames[slot]+'。';renderCards();}
document.querySelectorAll('[data-slot]').forEach(b=>{b.addEventListener('click',()=>{const slot=b.dataset.slot;if(selected){place(slot,selected);}else if(slots[slot]){const old=slots[slot];slots[slot]=null;selected=old;dragAnnouncement.textContent='已取回卡片，可以重新放置。';renderCards();}else{dragAnnouncement.textContent='请先选择一张卡片，再点击这里。';}});b.addEventListener('dragover',e=>{e.preventDefault();b.classList.add('over');});b.addEventListener('dragleave',()=>b.classList.remove('over'));b.addEventListener('drop',e=>{e.preventDefault();b.classList.remove('over');place(b.dataset.slot,e.dataTransfer.getData('text/plain'));});});renderCards();
$('checkDrag').addEventListener('click',()=>{const errors=[];if(slots.key!=='model')errors.push('空位①后面是模型名称 demo-small，因此字段名应是 "model"；messages 对应的是整个消息列表。');if(slots.role!=='user')errors.push('空位②是提问者的角色，应放 "user"；assistant 表示模型的回复。');if(slots.content!=='content')errors.push('空位③是 content 的值，应放具体提问“用一句话解释彩虹。”。');feedback('drag',errors,'拼对了！卡片组合成了和表单相同的 JSON 正文。字段名和值都要用双引号包起来。接下来试试“补全 JSON”。');if(!errors.length)showResponse('dragResponse',answers.rainbow);else $('dragResponse').hidden=true;});
const skeleton=JSON.stringify({model:'__填写__',messages:[{role:'system',content:'你是一位耐心的老师。'},{role:'__填写__',content:'__填写__'}]},null,2);$('jsonEditor').value=skeleton;
$('jsonEditor').addEventListener('input',()=>{$('writeResponse').hidden=true;});
$('formatJson').addEventListener('click',()=>{try{$('jsonEditor').value=JSON.stringify(JSON.parse($('jsonEditor').value),null,2);const el=$('feedback-write');el.className='feedback hint';el.textContent='缩进已整理。格式正确不代表内容符合任务，还可以点击“检查并模拟发送”。';}catch(e){feedback('write',['暂时无法整理：JSON 存在语法错误。先检查双引号、逗号和括号。'],'');}});
$('checkWrite').addEventListener('click',()=>{const result=Lesson.parseAndValidate($('jsonEditor').value);feedback('write',result.errors,'补全正确！你已经能把模型、角色和提问直接写进 JSON。正文只是请求的一部分，真实发送时仍需方法、地址和请求头。');if(!result.errors.length)showResponse('writeResponse',answers.eclipse);else $('writeResponse').hidden=true;});
const hints={ui:'提交通常用 POST。提问的人是 user。把“用一句话解释彩虹。”填入提问内容；不是把预期回答填进去。',drag:'① model 选择模型；② user 是提问者；③ content 的值是整句提问。assistant 和 messages 两张卡片在这次填空中用不到。',write:'按顺序把三个占位符替换为 demo-small、user、用一句话解释月食。保留外面的英文双引号和原有 JSON 结构。'};
document.querySelectorAll('[data-hint]').forEach(b=>b.addEventListener('click',()=>{const box=$('feedback-'+b.dataset.hint);box.className='feedback hint';box.textContent=hints[b.dataset.hint];}));
document.querySelectorAll('[data-reset]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.reset;completed.delete(id);updateProgress();$('feedback-'+id).replaceChildren();if(id==='ui'){$('requestForm').reset();updatePreview();}if(id==='drag'){slots={key:null,role:null,content:null};selected=null;dragAnnouncement.textContent='已重置，可以重新选择卡片。';renderCards();}if(id==='write'){$('jsonEditor').value=skeleton;$('writeResponse').hidden=true;}}));
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio);if(visible[0])document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+visible[0].target.id));},{rootMargin:'-15% 0px -45% 0px',threshold:[0,.1,.3]});document.querySelectorAll('main>section').forEach(s=>observer.observe(s));}
